package pe.greenminds.ecomind.community.infrastructure.persistence.jpa.assemblers;
import pe.greenminds.ecomind.community.domain.model.aggregates.Community;import pe.greenminds.ecomind.community.infrastructure.persistence.jpa.entities.CommunityPersistenceEntity;
public final class CommunityPersistenceAssembler{private CommunityPersistenceAssembler(){}public static Community toDomain(CommunityPersistenceEntity e){return new Community(e.getId(),e.getName(),e.getDescription(),e.getType(),e.getTopic(),e.getLocality(),e.getMemberLimit(),e.getIconUrl(),e.getCreatedBy());}public static CommunityPersistenceEntity toEntity(Community c){return new CommunityPersistenceEntity(c.getId(),c.getName(),c.getDescription(),c.getType(),c.getTopic(),c.getLocality(),c.getMemberLimit(),c.getIconUrl(),c.getCreatedBy());}}
